"""Certified paid-touch evaluation for the single-polynomial quadratic sieve."""
from __future__ import annotations

import math
from typing import Dict, List, Tuple


def primes_up_to(n: int) -> List[int]:
    s = bytearray([1]) * (n + 1)
    s[0:2] = b"\x00\x00"
    for i in range(2, int(n ** 0.5) + 1):
        if s[i]:
            s[i * i :: i] = bytearray(len(s[i * i :: i]))
    return [i for i in range(n + 1) if s[i]]


def sqrt_mod_prime(a: int, p: int) -> int:
    """Tonelli-Shanks square root of a quadratic residue a mod odd prime p."""
    a %= p
    if p % 4 == 3:
        return pow(a, (p + 1) // 4, p)
    q, s = p - 1, 0
    while q % 2 == 0:
        q, s = q // 2, s + 1
    z = 2
    while pow(z, (p - 1) // 2, p) != p - 1:
        z += 1
    m, c, t, r = s, pow(z, q, p), pow(a, q, p), pow(a, (q + 1) // 2, p)
    while t != 1:
        i, t2 = 0, t
        while t2 != 1:
            t2, i = t2 * t2 % p, i + 1
        b = pow(c, 1 << (m - i - 1), p)
        m, c, t, r = i, b * b % p, t * b * b % p, r * b % p
    return r


def certified_paid_touch(N: int, B: int, M: int) -> Tuple[int, float, int]:
    """Return (exact paid touch, closed form, error bound 2|S|-1)."""
    s = math.isqrt(N)
    if s * s < N:
        s += 1
    roots: Dict[int, List[int]] = {}
    for p in primes_up_to(B):
        if p == 2:
            roots[2] = [(1 - s) % 2]
        elif N % p and pow(N % p, (p - 1) // 2, p) == 1:
            x0 = sqrt_mod_prime(N, p)
            roots[p] = [(x0 - s) % p, (-x0 - s) % p]
    exact = sum(M // p + (1 if r < M % p else 0) for p, rs in roots.items() for r in rs)
    closed = 2 * M * sum(1.0 / p for p in roots if p != 2) + M / 2
    bound = 2 * len(roots) - 1
    assert abs(exact - closed) <= bound
    return exact, closed, bound


if __name__ == "__main__":
    for B in (150, 1200, 9600, 19000):
        print(B, certified_paid_touch(1353730821221, B, 150_000))

"""Fibre-best rule, regret decomposition and the zero-gain criterion."""
from __future__ import annotations

from collections import defaultdict
from typing import Dict, Hashable, List, Sequence, Tuple


def selection_report(cost: Dict[Tuple[Hashable, Hashable], float],
                     instances: Sequence[Hashable], ladder: Sequence[Hashable],
                     feature: Dict[Hashable, Hashable]) -> Dict[str, object]:
    """Compute oracle, fixed and fibre-best costs, the attaining rule g*,
    per-fibre regrets of the best fixed value, and the zero-gain verdict."""
    oracle = sum(min(cost[(i, b)] for b in ladder) for i in instances)
    fixed = {b: sum(cost[(i, b)] for i in instances) for b in ladder}
    b_fix = min(ladder, key=lambda b: fixed[b])
    fibre: Dict[Hashable, Dict[Hashable, float]] = defaultdict(lambda: {b: 0.0 for b in ladder})
    for i in instances:
        for b in ladder:
            fibre[feature[i]][b] += cost[(i, b)]
    g_star = {f: min(ladder, key=lambda b: row[b]) for f, row in fibre.items()}
    fibre_best = sum(fibre[f][g_star[f]] for f in fibre)
    regret = {f: fibre[f][b_fix] - fibre[f][g_star[f]] for f in fibre}
    assert oracle <= fibre_best + 1e-9 <= fixed[b_fix] + 2e-9
    assert abs((fixed[b_fix] - fibre_best) - sum(regret.values())) < 1e-9
    return {"oracle": oracle, "fibre_best": fibre_best, "best_fixed": b_fix,
            "fixed_cost": fixed[b_fix], "rule": g_star, "regret": regret,
            "zero_gain": all(r <= 1e-12 for r in regret.values())}


if __name__ == "__main__":
    I: List[str] = ["a", "b", "c", "d"]
    L = [300, 1200, 4800]
    c = {("a", 300): 3, ("a", 1200): 2, ("a", 4800): 4, ("b", 300): 5, ("b", 1200): 4,
         ("b", 4800): 1, ("c", 300): 2, ("c", 1200): 2.5, ("c", 4800): 3,
         ("d", 300): 4, ("d", 1200): 3, ("d", 4800): 3.5}
    print(selection_report(c, I, L, {"a": 0, "b": 1, "c": 0, "d": 1}))
